/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { Inbox, Folder, Plus, Settings } from 'lucide';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/layout.css';
import './navigation-sidebar.css';

type Destination = 'inbox' | 'drafts' | 'design';
export function createNavigationSidebar(dispatch: (action: string, value?: string) => void) {
  let selected: Destination = 'inbox';
  const render = () => <aside class="workspace-sidebar kui-layout" aria-label="Workspace navigation">
    <nav class="workspace-sidebar-body kui-sidebar kui-scroll-owner" aria-label="Workspace sections">
      <section class="kui-sidebar-section">
        <MenuHeader label="Workspace" />
        <MenuItem action="navigation.select" itemId="inbox" label="Inbox"
          icon={<LucideIcon icon={Inbox} name="inbox" />} selected={selected === 'inbox'} />
        <MenuItem action="navigation.select" itemId="drafts" label="Drafts"
          selected={selected === 'drafts'} />
      </section>
      <section class="kui-sidebar-section">
        <MenuHeader label="Projects" />
        <MenuItem action="navigation.select" itemId="design" label="Design system"
          icon={<LucideIcon icon={Folder} name="folder" />} selected={selected === 'design'} />
        <MenuItem action="navigation.select" itemId="archive" label="Archive"
          disabled trailing={<span>Admin only</span>} title="Archive requires administrator access" />
        <div class="kui-sidebar-surface">
          <strong>Northstar workspace</strong>
          <p>12 active projects. Next milestone: accessible navigation.</p>
        </div>
      </section>
    </nav>
    <footer class="workspace-sidebar-footer">
      <Toolbar label="Sidebar actions" divider={false}
        leading={<ToolbarControlGroup appearance="borderless" single>
          <button type="button" data-action="project.create" aria-label="Add project">
            <LucideIcon icon={Plus} name="plus" />
          </button>
        </ToolbarControlGroup>}
        trailing={<ToolbarControlGroup appearance="borderless" single>
          <button type="button" data-action="workspace.settings" aria-label="Workspace settings">
            <LucideIcon icon={Settings} name="settings" />
          </button>
        </ToolbarControlGroup>} />
    </footer>
  </aside>;
  function connect(root: HTMLElement, invalidate: () => void) {
    return delegate(root, 'click', '[data-action]', (_event, element) => {
      const action = element.getAttribute('data-action');
      if (action === 'navigation.select') {
        const id = element.getAttribute('data-item-id');
        if (id !== 'inbox' && id !== 'drafts' && id !== 'design') return;
        selected = id;
        dispatch('navigation.select', id);
        invalidate();
      } else if (action === 'project.create' || action === 'workspace.settings') {
        dispatch(action);
      }
    });
  }
  return { render, connect };
}

