.workspace-sidebar { min-width:0; height:100%; display:grid; grid-template-rows:minmax(0,1fr) auto; color:var(--kui-color-text); background:var(--kui-color-surface); }
.workspace-sidebar-body { min-height:0; padding-block:var(--kui-layout-pane-inset); }
.workspace-sidebar-footer { border-block-start:1px solid var(--kui-color-border); }
.workspace-sidebar .kui-sidebar-surface { overflow-wrap:anywhere; }
.workspace-sidebar p { margin-block:var(--kui-space-xs) 0; color:var(--kui-color-text-quiet); }
.workspace-sidebar :focus-visible { outline:var(--kui-focus-ring); outline-offset:2px; }
/* sidebar.css owns the single horizontal gutter and shared icon/label grid.
   No pane inset is layered over it; the footer's Toolbar owns its chrome. */
